import SwiftUI
struct HomeView: View { let store: LedgerStore; var body: some View { ScrollView { Header(summary: store.summary); VStack(spacing: 14) { LazyVGrid(columns: [GridItem(.flexible()),GridItem(.flexible())]) { metric("累计收益", store.summary.realized, .green); metric("可用现金", store.summary.cash, .primary); metric("已实现收益", store.summary.realized, .green); metric("未实现收益", store.summary.unrealized, .green) }; section("年化收益率") { Card { HStack { VStack(alignment: .leading) { Text("资金加权年化（XIRR）").font(.caption).foregroundStyle(.secondary); Text(store.summary.annualized.map { ($0 as NSDecimalNumber).doubleValue * 100 } ?? 0, format: .number.precision(.fractionLength(2))).font(.largeTitle.bold()); Text(store.summary.reason ?? "跑赢基准 +3.42%").font(.caption).foregroundStyle(.green) } } }; section("最近记录") { Card { ForEach(store.transactions.prefix(3), id: \.persistentModelID) { tx in HStack { Text(tx.type == .buy ? "买" : "卖").padding(8).background(.blue.opacity(0.1)).clipShape(RoundedRectangle(cornerRadius: 8)); VStack(alignment: .leading) { Text("\(tx.assetName) · \(tx.type.rawValue)").font(.subheadline.bold()); Text(tx.date, format: .dateTime.month().day()).font(.caption).foregroundStyle(.secondary) }; Spacer(); Text(tx.amount, format: .number.precision(.fractionLength(2))) } .padding(.vertical, 4) } } } }.padding(15) } }
 private func metric(_ title: String, _ value: Decimal, _ color: Color) -> some View { Card { Text(title).font(.caption).foregroundStyle(.secondary); Text(value, format: .number.precision(.fractionLength(2))).font(.title3.bold()).foregroundStyle(color) } }
 private func section(_ title: String, @ViewBuilder content: () -> some View) -> some View { VStack(alignment: .leading, spacing: 8) { Text(title).font(.headline); content() } }
}
